declare(strict_types=1);session_start();require dirname(__DIR__).'/config/config.php';require_sign_in();$role=(string)($_SESSION['role']??'');if(!in_array($role,['hr','director','sub_director','headteacher'],true)){http_response_code(403);exit('Your role cannot access staff profiles.');}$uid=(int)$_SESSION['user_id'];$q=db()->prepare('SELECT s.id,s.name FROM schools s JOIN school_memberships m ON m.school_id=s.id WHERE m.user_id=? ORDER BY s.name');$q->execute([$uid]);$schools=$q->fetchAll();$ids=array_map('intval',array_column($schools,'id'));$requested=(int)($_GET['school_id']??($ids[0]??0));$school=in_array($requested,$ids,true)?$requested:0;
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Staff profiles · ShuleLite</title><link rel="stylesheet" href="assets/app.css"><script defer src="assets/app.js"></script><script defer src="assets/staff-profiles.js"></script></head><body><div class="app-shell"><?php require __DIR__.'/sidebar.php';?><main class="main-area"><header class="topbar"><button class="icon-button menu-toggle" data-menu aria-label="Open navigation" aria-expanded="false">☰</button><div class="crumb">People <span>/</span> Staff profiles</div><div class="top-actions"><span class="role-chip"><?=e(str_replace('_',' ',$role))?></span></div></header><div class="page-content" data-staff-profiles data-api="api/employee_profiles.php" data-school="<?=$school?>" data-role="<?=e($role)?>" data-csrf="<?=e(csrf_token())?>"><section class="welcome-row"><div><div class="eyebrow">HUMAN RESOURCES</div><h1>Staff profiles</h1><p class="muted">Employment profile details are stored separately from login accounts and contract records.</p></div><?php if(count($schools)>1):?><form method="get"><label for="staff-profile-school">School</label><select id="staff-profile-school" name="school_id" onchange="this.form.submit()"><?php foreach($schools as $s):?><option value="<?=$s['id']?>"<?=(int)$s['id']===$school?' selected':''?>><?=e($s['name'])?></option><?php endforeach;?></select></form><?php endif;?></section><?php if(!$school):?><div class="empty-state"><h2>No school is linked</h2><p>Ask a school administrator to link your account.</p></div><?php else:?><div data-staff-status class="notice" role="status" aria-live="polite" hidden></div><?php if($role==='hr'):?><section class="note-create"><div class="section-heading"><h2>Add or update employee details</h2></div><form data-staff-profile-form class="note-form"><div class="form-grid"><div><label for="staff-profile-user">Staff account</label><select id="staff-profile-user" name="user_id" required></select></div><div><label for="staff-profile-number">Employee number</label><input id="staff-profile-number" name="employee_number" maxlength="60"></div><div><label for="staff-profile-title">Job title</label><input id="staff-profile-title" name="job_title" maxlength="140"></div><div><label for="staff-profile-department">Department</label><input id="staff-profile-department" name="department" maxlength="120"></div><div><label for="staff-profile-type">Employment type</label><select id="staff-profile-type" name="employment_type"><option value="">Not specified</option><option value="full_time">Full time</option><option value="part_time">Part time</option><option value="casual">Casual</option><option value="volunteer">Volunteer</option><option value="contract">Contract</option></select></div></div><button class="button primary" type="submit">Save profile</button></form></section><?php endif;?><section class="content-section"><div class="section-heading"><div><div class="eyebrow">SCHOOL TEAM</div><h2>Employee records</h2></div><button class="button" type="button" data-staff-refresh>Refresh</button></div><div class="table-wrap" data-staff-list><p class="muted">Loading staff profiles…</p></div></section><?php endif;?><footer class="page-footer">ShuleLite · Staff profiles</footer></div></main></div></div></body></html>
